<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
putenv('PERSONAL_DATA_KEY='.base64_encode(str_repeat('D',32)));
require_once __DIR__.'/../app/db.php';
require_once __DIR__.'/../app/subscriber_radius.php';
require_once __DIR__.'/../app/partner_hotspots.php';
$checks=0;function subscriber_domain_expect(bool $ok,string $message):void{global$checks;$checks++;if(!$ok)throw new RuntimeException($message);}
$pdo=db();$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);
